    "content": "新华社杭州8月9日电（记者唐弢、黄筱）今年第13号台风“白海豚”正向我国华东沿海逼近。气象部门预测，与此前影响我国的台风“巴威”相似，“白海豚”同样有可能在经历长途奔袭后，将正面登陆浙江。 8月8日夜间，温州乐清市清江镇蔡岙村党员志愿者对村内海塘进行巡查。新华社记者 江汉 摄 今年7月至8月，西北太平洋副热带高压异常强盛，呈东西向带状稳定盘踞在我国东部至日本以南海域。浙江省气象台首席预报员周玲丽表示，副高南侧盛行的偏东气流，就像一条横贯西太平洋的“大气传送带”，将生成于远洋的台风一路向西输送。台风“巴威”和“白海豚…"
