    "description": "湖北老河口市人民政府联合调查组8月9日发布情况通报： 针对媒体报道我市洪山嘴镇小黄楝树村“幸福坝”相关问题，我市高度重视，第一时间成立由纪检监察、公安、司法等部门组成的联合调查组，组织开展全面调查工作。 后续，我们将严格依据调查结果依法处置，及时、准确、公开向社会发布相关情况，回应公众关切。感谢媒体关注监督！ 据“都市现场”微信公号此前消息，湖北襄阳有网友发布视频称，老河口市“幸福坝”灌溉水坝被隔成鱼塘，五百多亩农田抗旱用水没有保障。 …",
    "content": "湖北老河口市人民政府联合调查组8月9日发布情况通报： 针对媒体报道我市洪山嘴镇小黄楝树村“幸福坝”相关问题，我市高度重视，第一时间成立由纪检监察、公安、司法等部门组成的联合调查组，组织开展全面调查工作。 后续，我们将严格依据调查结果依法处置，及时、准确、公开向社会发布相关情况，回应公众关切。感谢媒体关注监督！ 据“都市现场”微信公号此前消息，湖北襄阳有网友发布视频称，老河口市“幸福坝”灌溉水坝被隔成鱼塘，五百多亩农田抗旱用水没有保障。 据了解，幸福坝大概有三四十亩水面，是一个比水库还小的堰塘，承包人就在这30多亩水…"
