    "content": "新华社上海8月9日电（记者陈浩明）记者9日从上海市气象局了解到，受台风“白海豚”影响，上海已出现明显风雨天气，呈现“面强点极端”的特点。截至9日12时，上海已针对多区发布暴雨红色预警信号。 上海市气象台已于9日10时30分针对中心城区发布暴雨红色预警信号：预计未来6小时内，中心城区大部分地区6小时累积降水量将达220毫米以上。浦东新区气象台和闵行区气象台分别于9日10时30分、12时发布暴雨红色预警信号。 据预测，台风“白海豚”9日至11日对上海将有明显风雨影响。其间，过程累积雨量为150至180毫米，局部地区达2…"
