    "description": "新华社海牙8月9日电 记者手记｜从防洪到抗旱，荷兰经历气候变化之痛 新华社记者邵海军 李弘 莱茵河从德国进入荷兰之后不久即分流，南边的一支被称作瓦尔河。瓦尔河在荷兰东部城市奈梅亨拐了个急弯，历史上这里洪涝灾害多发，如今却是另一番景象。 记者近日在这里看到，瓦尔河的水位明显下降，河床大面积裸露，高温炙烤下的河畔细沙随风被吹上街道。原本这个季节经常在河上休闲的私人船舶扎堆停在码头，有的甚至已经搁浅。瓦尔河上往来货船的吃水明显变浅，不少船舶装…",
    "content": "新华社海牙8月9日电 记者手记｜从防洪到抗旱，荷兰经历气候变化之痛 新华社记者邵海军 李弘 莱茵河从德国进入荷兰之后不久即分流，南边的一支被称作瓦尔河。瓦尔河在荷兰东部城市奈梅亨拐了个急弯，历史上这里洪涝灾害多发，如今却是另一番景象。 记者近日在这里看到，瓦尔河的水位明显下降，河床大面积裸露，高温炙烤下的河畔细沙随风被吹上街道。原本这个季节经常在河上休闲的私人船舶扎堆停在码头，有的甚至已经搁浅。瓦尔河上往来货船的吃水明显变浅，不少船舶装载量只有70%，甚至一半。 这种情况让不少荷兰人感到吃惊。40岁的巴特专程从70…"
