    "content": "新华社南昌8月9日电（记者范帆）受台风“白海豚”逼近影响，江西部分地区将出现大风及强降雨过程。为做好防范应对工作，江西省防汛抗旱指挥部决定自8月9日9时起启动防汛四级应急响应。 气象预报显示，8月10日至11日，赣北、赣中阴天有中到大雨，部分地区有暴雨和大暴雨，赣南阴天多云有阵雨，局部地区有大到暴雨，江湖水面、平原河谷、高海拔山区阵风可达8级至10级。8月12日，台风或与冷空气结合，江西北部局地仍有暴雨。 气象部门提醒，当前正值暑期旅游旺季，叠加台风“白海豚”带来的强降雨影响，峡谷、山涧溪流周边区域山洪风险陡增，有…"
