    "content": "当地时间2026年8月8日，西班牙马德里，一名来自意大利的乘客在巴拉哈斯机场与媒体人员交谈。西班牙政府决定对来自意大利的旅客实施临时边境检查，此前意大利政府拒绝取消其对来自西班牙旅客的管制措施。视觉中国 图 西班牙与意大利因休达“偷渡潮”引发的争端升级。西班牙于当地时间8日开始在港口与机场对从意大利入境的旅客实施随机抽查，该措施暂定执行至9月7日。一周前，意大利出台了类似限制措施。而社交媒体上的虚假信息仍在传播，各方警惕可能发生的新一轮越境危机。 据新华社报道，西班牙实施边境管控措施给出的理由是，意大利正持续面临非…"
