    "content": "新华社日本长崎8月9日电（记者陈泽安 李林欣）日本长崎遭原子弹轰炸81周年纪念仪式9日在长崎市和平纪念公园举行。日本首相高市早苗参加仪式，其致辞时对“无核三原则”仍含糊表态，未明确表示日本将继续坚持该原则。 高市9日关于“无核三原则”的表态沿用了她6日在广岛遭原子弹轰炸81周年纪念仪式上致辞时的表述。当时，高市早苗在致辞中仅提及“日本现在坚持‘无核三原则’”，但其措辞与历任日本首相略有不同，且未明确表示日本将继续坚持该原则。 日本在野党此前表示，高市的表述仅仅是说明现状，缺乏今后继续坚持“无核三原则”的决心。 “无…"
