    "content": "新华社阿比让8月9日电 专访｜中国零关税举措开启中非经贸合作新阶段——访尼日尔工商会经济专家马加吉 新华社记者张健 “中国零关税举措为中非经贸合作注入新动力，也将为非洲工业化和经济发展带来新的历史机遇。”尼日尔工商会经济专家阿马杜·马加吉日前接受新华社记者专访时表示，这一举措体现了中国推动共同发展、坚持互利共赢的承诺，标志着中非经贸合作迈入新的发展阶段。 马加吉说，零关税举措不仅具有重要经贸意义，更体现了中国始终致力于推动共同发展、促进更加包容的经济全球化。这是落实中非合作论坛成果的重要举措，将有力支持非洲工业化进…"
