    "content": "新华社呼和浩特8月9日电 据内蒙古自治区纪委监委通报，经内蒙古自治区党委批准，内蒙古自治区纪委监委对内蒙古自治区体育局原党组成员、副局长吴刚严重违纪违法问题进行了立案审查调查。 经查，吴刚丧失理想信念，背弃初心使命，无视中央八项规定精神，廉洁底线失守，收受管理和服务对象礼品、礼金，借用管理和服务对象车辆、钱款；组织原则缺失，不按规定报告个人有关事项；工作中不负责任、疏于管理，对上级决策部署督促推动不到位，造成工程施工严重拖延，干预插手工程项目招投标；践踏党纪国法，将公权力异化为谋取私利的工具，利用职务便利和职权地位…"
