    "pub_date": "2026-08-09 12:10:26",
    "author": "吴頔/上观新闻",
    "description": "台风“白海豚”逼近，对上海风雨影响持续增强，防汛形势严峻。上海市委副书记、市长龚正今天（8月9日）主持召开台风“白海豚”防御应对工作视频调度会议，对做好台风防御应对进行再检查、再部署、再落实。龚正指出，要全面贯彻落实习近平总书记关于防汛救灾工作的重要指示批示精神，按照市委部署要求，坚持“四早五最”，咬定“不死人、少伤人、少损失”的目标，以更高标准、更严要求、更实举措，织牢织密防汛防台安全网，打好防汛防台主动仗，坚决守住城市安全底线。 上…",
    "content": "台风“白海豚”逼近，对上海风雨影响持续增强，防汛形势严峻。上海市委副书记、市长龚正今天（8月9日）主持召开台风“白海豚”防御应对工作视频调度会议，对做好台风防御应对进行再检查、再部署、再落实。龚正指出，要全面贯彻落实习近平总书记关于防汛救灾工作的重要指示批示精神，按照市委部署要求，坚持“四早五最”，咬定“不死人、少伤人、少损失”的目标，以更高标准、更严要求、更实举措，织牢织密防汛防台安全网，打好防汛防台主动仗，坚决守住城市安全底线。 上午，龚正一行来到市城市运行管理中心，视频连线市气象局、市水务局、市应急局、市交通…"
