    "content": "截至8月7日收盘，现货黄金本周上涨264.13美元，涨幅7.44%，报4341.91美元/盎司；纽约商品交易所8月交割的COMEX黄金期货本周上涨291.60美元，涨幅7.17%，报4401.3美元/盎司，双双创下1月23日当周以来最大单周涨幅。消息面上，当地时间8月7日，美国劳工统计局公布的美国7月非农就业人数大幅低于预期。市场对美联储9月维持利率不变的预期升温，美元指数应声下跌，推动金价和银价显著上涨。瑞银的观点指出，金价大幅反弹主要源于市场对霍尔木兹海峡重开预期日益增强的提振。据央视新闻报道，当地时间8月6日…"
