    "content": "新华社北京8月9日电（记者田晨旭）北京气象部门8日介绍，从7月27日以来，今年第13号台风“白海豚”经过长途跋涉、多次眼墙置换和强度变化，目前正在朝我国华东沿海靠近，预计将于9日晚至10日晨登陆。 据介绍，目前台风登陆后的路径预报仍有分歧，预计主要有两种可能： 第一种是登陆后直接转向西北偏北方向，台风残余环流可能合并到华北冷涡系统中，在华北一带维持两到三天。受其影响，12日至15日京津冀地区将出现持续性强降水，过程累计雨量有极端性，但强降雨落区存在差异。预计北京地区可能有暴雨到大暴雨，部分地区有特大暴雨。 第二种路…"
