    "content": "新华社德黑兰8月9日电 据伊朗新闻电视台8日报道，伊朗最高国家安全委员会秘书佐勒加德尔表示，如果美国不改变其行为，霍尔木兹海峡将维持关闭状态，重开霍尔木兹海峡的前提是美国满足永久停止对伊军事行动等5个条件。 报道说，这些条件包括永久停止对伊朗及其地区盟友的军事行动，停止威胁或侮辱伊朗，解除对伊朗海上封锁和全部制裁，归还伊朗被冻结资产，赔偿相关军事行动给伊朗造成的损失。 另据伊朗法尔斯通讯社8日报道，伊朗外长阿拉格齐当天表示，伊朗与阿曼“接近”达成协议，但并不意味着重新开放霍尔木兹海峡，“海峡的开放还取决于其他条件，…"
