    "content": "新华社华盛顿8月8日电（记者杨伶 熊茂伶）据美国《华盛顿邮报》8日报道，伊朗战事导致美国武器库存锐减，美国国防部日前已要求美军工企业迅速提升武器的生产和交付能力，其中包括因伊朗战事而极度短缺的弹药。 报道援引一份美国防部的备忘录说，国防部副部长史蒂夫·范伯格5日致信美军工企业负责人，要求他们必须在21天内提交计划，以大幅加快武器交付进度，提高关键装备的产能。范伯格在信中称：“长达数年的研发周期是不可接受的。我们必须立即大幅加快项目进度，并扩大生产能力。” 另据美国《纽约时报》8日援引消息人士的话报道，美国在同伊朗的…"
