    "description": "最近一周（8月3日—8月7日），A股市场震荡反弹，三大指数周线均实现上涨，科技成长板块表现尤为强势。资金面上，当周沪深两市主力资金合计净流入664.04亿元。电子、通信、有色金属板块获主力资金大幅净买入，电子、通信两大板块主力资金合计净流入近600亿元；传媒、计算机板块遭主力资金净流出。（财联社）",
    "content": "最近一周（8月3日—8月7日），A股市场震荡反弹，三大指数周线均实现上涨，科技成长板块表现尤为强势。资金面上，当周沪深两市主力资金合计净流入664.04亿元。电子、通信、有色金属板块获主力资金大幅净买入，电子、通信两大板块主力资金合计净流入近600亿元；传媒、计算机板块遭主力资金净流出。（财联社）"
