    "description": "新华社东京8月9日电（记者陈泽安 梁晨）据日本共同社9日报道，8日晚，日本长野县一条道路因山体滑坡无法通行。截至当地时间9日5时30分，可能有约390人被困。",
    "content": "新华社东京8月9日电（记者陈泽安 梁晨）据日本共同社9日报道，8日晚，日本长野县一条道路因山体滑坡无法通行。截至当地时间9日5时30分，可能有约390人被困。"
