    "content": "——国家统计局城市司首席统计师董莉娟解读2026年7月份CPI和PPI数据 7月份，受国际输入性因素影响，居民消费价格指数（CPI）环比下降0.1%，同比上涨0.5%，扣除食品和能源价格的核心CPI环比上涨0.3%，同比上涨0.9%，CPI总体保持温和上涨。国内部分行业需求增加，但受输入性和季节性等因素影响，工业生产者出厂价格指数（PPI）环比下降0.7%，同比上涨3.5%，涨幅比上月回落0.6个百分点。 一、CPI环比降幅收窄，同比温和上涨 从环比看，全国CPI下降0.1%，降幅比上月收窄0.2个百分点。国际市场…"
