    "content": "7月24日，作家赵阳与学生们交流。新华社记者 朱炜 摄 新华社香港8月9日电 题：1872香港少年作家班的青春笔墨 黄茜恬 在香港有一群中学生，周末最惦念的去处，是1872香港少年作家班。 来自数十所中学的少年们围坐一室，各有一段被文字治愈的心事。英华书院的王喆借文字安放青春期的敏感；中华基金中学的梁梓朗在研学中读懂家国；圣类斯中学的黎健邦以写作搭建亲情纽带…… 两小时的课堂不刷题、不押题，只共读经典、分享习作。四载时光流转，在作家赵阳的陪伴引导下，不少从前课余沉溺电子产品、对中文写作提不起兴趣的孩子，成长为懂得体…"
