    "pub_date": "2026-08-09 09:08:50",
    "author": "",
    "description": "习近平党建思想，是习近平新时代中国特色社会主义思想的重要组成部分，是加强新时代党的建设的根本遵循。要深刻理解和把握习近平党建思想的内涵要义，必须深刻领会“十四个坚持”。 新华社“学习新语”栏目推出“铸魂强党”系列融合报道。本期围绕“坚持健全上下贯通、执行有力的组织体系”，系统梳理党的十八大以来习近平总书记的重要论述，一起学习领会。 策划：石锋 吴丹 统筹：黄庆华 周年钧 文案：王浩程 新华社新媒体中心制作 新华社出品",
    "content": "习近平党建思想，是习近平新时代中国特色社会主义思想的重要组成部分，是加强新时代党的建设的根本遵循。要深刻理解和把握习近平党建思想的内涵要义，必须深刻领会“十四个坚持”。 新华社“学习新语”栏目推出“铸魂强党”系列融合报道。本期围绕“坚持健全上下贯通、执行有力的组织体系”，系统梳理党的十八大以来习近平总书记的重要论述，一起学习领会。 策划：石锋 吴丹 统筹：黄庆华 周年钧 文案：王浩程 &nbsp; 新华社新媒体中心制作 新华社出品"
