    "author": "",
    "description": "“我只是拉了个群”“视频不是我发的”“大家都在转，我只是看看热闹”……现实中，一些未成年人将网络“吃瓜”当成同学之间的普通玩笑，却忽视了隐私视频、照片一旦发布到网络空间，便可能在微信群、朋友圈等社交平台不断转发、扩散，最终演变成一场网络暴力。",
    "content": "“我只是拉了个群”“视频不是我发的”“大家都在转，我只是看看热闹”……现实中，一些未成年人将网络“吃瓜”当成同学之间的普通玩笑，却忽视了隐私视频、照片一旦发布到网络空间，便可能在微信群、朋友圈等社交平台不断转发、扩散，最终演变成一场网络暴力。"
