    "author": "黄泽民,杨依然",
    "description": "以色列军警日前在约旦河西岸中部拉姆安拉附近的卡兰迪亚难民营发起大规模军事行动。新华社记者在现场蹲守八个多小时，目睹多名巴勒斯坦人遭以军逮捕，记者本人也一度被以军枪口对准。 据悉，以军经常以“反恐”为由，在巴勒斯坦约旦河西岸开展各类军事行动。难民营当地居民告诉记者，此次军事行动前后持续两天，共有数十名巴勒斯坦人被抓捕。据巴勒斯坦通讯社报道，该行动造成至少48名巴勒斯坦人受伤。 据以色列媒体报道，以色列军方人士证实了此次在卡兰迪亚难民营的行…",
    "content": "以色列军警日前在约旦河西岸中部拉姆安拉附近的卡兰迪亚难民营发起大规模军事行动。新华社记者在现场蹲守八个多小时，目睹多名巴勒斯坦人遭以军逮捕，记者本人也一度被以军枪口对准。 据悉，以军经常以“反恐”为由，在巴勒斯坦约旦河西岸开展各类军事行动。难民营当地居民告诉记者，此次军事行动前后持续两天，共有数十名巴勒斯坦人被抓捕。据巴勒斯坦通讯社报道，该行动造成至少48名巴勒斯坦人受伤。 据以色列媒体报道，以色列军方人士证实了此次在卡兰迪亚难民营的行动，但同时强调行动规模“有限”。该消息人士称，此次行动旨在削弱该地区武装组织实力…"
