    "content": "新华社济南8月8日电（记者王欢、张武岳、李小波）“快看，红色龙舟划手配合得好，要赶上来了！” “那个鼓手年龄小，动作真专业！” 在山东日照奥林匹克水上运动小镇，加油的锣鼓与整齐的口号吸引市民游客围观，一场海上龙舟比赛正在进行。刚冲线的10岁鼓手陈宇欣是东港区小学四年级学生，虽然身上的衣服被海水和汗水湿透，但他脸上洋溢着喜悦：“参加海上龙舟比赛，不仅锻炼了身体，增强了团队合作意识，我还学习到了龙舟相关的中华传统文化知识，收获很大。” 陈宇欣眼前的这片碧波，多年前曾是养殖鱼虾的滩涂。经过重新规划建设，如今的水上运动小镇…"
