    "content": "7月30日，中外青年在山东大学考古实验室实践。新华社发（山东大学考古学院供图） 新华社济南8月8日电（记者张昕怡）盛夏时节，在位于青岛即墨的山东大学博物馆六楼空地上，来自加拿大卡尔加里大学的人类学学生伊莎贝尔正和同伴围坐在一起，打磨一枚石簇。用简单的工具敲凿石块，再用粗砂纸打磨，使之变得尖利，模仿古人类制作原始工具的过程，给她带来了全新体验。 7月中旬至8月初，由山东大学考古学院（文化遗产研究院）、山东大学博物馆联合主办的第三届山东大学“中国考古学”国际暑期学校在青岛举行，来自美国、加拿大、俄罗斯、南非等四大洲10…"
