    "content": "2026年08月09日 由国家发展改革委、国家能源局编制印发的《可再生能源消费最低比重目标和可再生能源电力消纳责任权重制度实施办法》（以下简称《办法》）近期施行。什么是消费最低比重？《办法》如何促进可再生能源高质量发展？记者进行了采访。 问：《办法》出台的背景和意义是什么？ 答：简单来讲，《办法》的主要目标在于引导全社会优先使用和主动消费可再生能源，助力实现碳达峰碳中和。 长期以来，我国可再生能源产业发展重心在供给侧扩张，推动我国可再生能源装机规模持续攀升。截至今年6月底，全国可再生能源装机达到24.55亿千瓦，同…"
