    "description": "2026年08月09日 吕桂明摄（影像中国） \"> 新华社记者 陶 亮摄 \"> 孙凯芳摄（影像中国） \"> 暑期以来，旅游市场火热。各地依托自然人文资源，文旅融合、科技赋能，推出丰富玩法，让游客尽享乐趣。 2026-08-09 00:00:00:0 30173784 10http://paper.people.com.cn/rmrb/pc/content/202608/09/content_30173784.htmlhttp://pap…",
    "content": "2026年08月09日 6日，游客在黄河壶口瀑布景区观赏瀑布，感受黄河水的磅礴气势。 吕桂明摄（影像中国） \"> 6日，贵州威宁彝族回族苗族自治县，人们在篝火旁载歌载舞。 新华社记者 陶 亮摄 \"> 6日，重庆沙坪坝区，小朋友在室内滑雪场体验反季滑雪乐趣。 孙凯芳摄（影像中国） \"> 暑期以来，旅游市场火热。各地依托自然人文资源，文旅融合、科技赋能，推出丰富玩法，让游客尽享乐趣。 2026-08-09 00:00:00:0 30173784 1 0 http://paper.people.com.cn/rmrb/p…"
