    "pub_date": "2026-08-09 08:26:04",
    "author": "",
    "description": "2026年08月09日 在河北石家庄市国际生物医药园，一款乳膏产品，从研发到上市耗时不到一年。“这是公司最近几年通过创新跑出的新速度、创下的新纪录。”河北纳科生物科技有限公司质量总监于月欣说。 这么快，怎么做到的？答案藏在距离纳科生物不足百米的河北省药品医疗器械检验研究院石家庄实验室里。 “上市前检验是产品从研发走向上市的关键环节，耗时较长。”医药园管委会副主任高健说，实验室成立以前，园区内企业的医疗器械产品要上市，需自行将样品送到石家…",
    "content": "2026年08月09日 在河北石家庄市国际生物医药园，一款乳膏产品，从研发到上市耗时不到一年。“这是公司最近几年通过创新跑出的新速度、创下的新纪录。”河北纳科生物科技有限公司质量总监于月欣说。 这么快，怎么做到的？答案藏在距离纳科生物不足百米的河北省药品医疗器械检验研究院石家庄实验室里。 “上市前检验是产品从研发走向上市的关键环节，耗时较长。”医药园管委会副主任高健说，实验室成立以前，园区内企业的医疗器械产品要上市，需自行将样品送到石家庄鹿泉区做检测，光往返路程就要两小时。 往返奔波不说，让于月欣头疼的是，申报时如…"
