    "author": "",
    "description": "2026年08月09日 本报北京8月8日电 （记者李心萍、窦瀚洋）8日，浙江杭州经绍兴至台州高铁温岭至玉环段（以下简称“杭台高铁温玉段”）开通运营，玉环从此结束不通铁路的历史，迈入高铁时代。 杭台高铁温玉段是杭台高铁的延伸线路，位于台州市南部，新建正线长约37公里，设计时速350公里，设温岭、温岭西、玉环3座车站。杭台高铁温玉段开通后，台州市实现“县县通铁路”。 该线路于2022年11月全面开工建设，坚持生态优先、绿色低碳理念，桥隧比高…",
    "content": "2026年08月09日 本报北京8月8日电&nbsp;&nbsp;（记者李心萍、窦瀚洋）8日，浙江杭州经绍兴至台州高铁温岭至玉环段（以下简称“杭台高铁温玉段”）开通运营，玉环从此结束不通铁路的历史，迈入高铁时代。 杭台高铁温玉段是杭台高铁的延伸线路，位于台州市南部，新建正线长约37公里，设计时速350公里，设温岭、温岭西、玉环3座车站。杭台高铁温玉段开通后，台州市实现“县县通铁路”。 该线路于2022年11月全面开工建设，坚持生态优先、绿色低碳理念，桥隧比高达90.34%，建成17座桥梁、13座隧道。 杭台高铁是我…"
