    "content": "2026年08月09日 巴基斯坦北部山区喀喇昆仑公路达苏段改线工程项目现场，驻地医生雷马特·阿里（中文名茹涵）一大早就来到了诊所。施工现场山势陡峭、岩体破碎、道路狭窄，每逢爆破作业开始前，茹涵总会提前检查好救护车、急救箱和药品。这样的工作节奏，他和同事们已经坚持了11年。2022年，茹涵获得由中国国际文化交流中心和人民日报《环球人物》杂志社联合主办的第二届“丝路友好使者”荣誉称号。 “我从未因工作环境艰险而产生退缩的念头。”日前在北京接受采访时，茹涵说，“中国人可以离开家乡帮助巴基斯坦修路，为什么我不能为自己的国家…"
