    "author": "",
    "description": "2026年08月09日 盛溪川摄 \"> 新华社记者 郭绪雷摄 \"> 陈 彬摄 \"> 在江南水乡，新昌调腔的古韵婉转从古老戏台流向现代剧场；在中原大地，罗卷戏的粗犷豪歌正从田间地头传向更远的地方；在岭南汕尾，白字戏的“啊咿嗳”衬词拉腔透过手机屏幕飘向海内外。 数据显示，我国现存戏曲剧种348个，其中约65%属于稀有剧种。这些散落在中华大地上的稀有剧种，以独特的地方语调、多样的表演程式和丰富的情感表达，承载着一方水土的记忆，是文化多样性的生…",
    "content": "2026年08月09日 新昌调腔《北西厢》剧照。 盛溪川摄 \"> 第二届中国戏曲稀有剧种优秀剧目展演中，安徽省的徽京剧演员在表演。 新华社记者 郭绪雷摄 \"> 第二届中国戏曲稀有剧种优秀剧目展演的后台，来自贵州省黔剧院的演员准备上场。 陈 彬摄 \"> 在江南水乡，新昌调腔的古韵婉转从古老戏台流向现代剧场；在中原大地，罗卷戏的粗犷豪歌正从田间地头传向更远的地方；在岭南汕尾，白字戏的“啊咿嗳”衬词拉腔透过手机屏幕飘向海内外。 数据显示，我国现存戏曲剧种348个，其中约65%属于稀有剧种。这些散落在中华大地上的稀有剧种，…"
