    "description": "2026年08月09日 马头墙错落有致，古巷清幽绵长。盛夏时节，临近傍晚，皖南的燥热终于慢慢消散。在安徽省宣城市绩溪县上庄镇瑞川村，村中的孩童们一边嬉闹一边往村东的东场咖啡店走去。 走进东场咖啡店，木梁雕花、青石院落，徽派建筑的古朴典雅之气扑面而来。店中除了咖啡，最多的便是各类书籍。而来到此处的孩童，三三两两围在桌前，读书习字。 东场咖啡店的负责人侯宪民介绍，此处原是村中一座废弃民宅，可追溯至清末民初。2024年末，他将这里租下，经营咖…",
    "content": "2026年08月09日 马头墙错落有致，古巷清幽绵长。盛夏时节，临近傍晚，皖南的燥热终于慢慢消散。在安徽省宣城市绩溪县上庄镇瑞川村，村中的孩童们一边嬉闹一边往村东的东场咖啡店走去。 走进东场咖啡店，木梁雕花、青石院落，徽派建筑的古朴典雅之气扑面而来。店中除了咖啡，最多的便是各类书籍。而来到此处的孩童，三三两两围在桌前，读书习字。 东场咖啡店的负责人侯宪民介绍，此处原是村中一座废弃民宅，可追溯至清末民初。2024年末，他将这里租下，经营咖啡生意，也因喜欢读书，购置了一些书籍、连环画。如今，不仅游客前来打卡，更成了村中…"
