    "author": "张建新,栗雅婷",
    "description": "新华社天津8月8日电（记者张建新、栗雅婷）肾结石是泌尿系统常见疾病，而炎热的夏秋季节正是其高发期。专家提醒，高温天气下人体水分流失加快，加上不良饮食习惯和久坐不动等因素，会显著增加肾结石的发生风险。预防肾结石应牢记三个关键原则：喝够水、管住嘴、迈开腿，从日常生活的细节入手，降低患病几率。 天津市第一中心医院肾内科主任、主任医师常文秀表示，高温天气人体水分从汗液排走，若饮水跟不上，原本溶解在尿液里的钙、草酸、尿酸等物质就会因浓度过高形成结…",
    "content": "新华社天津8月8日电（记者张建新、栗雅婷）肾结石是泌尿系统常见疾病，而炎热的夏秋季节正是其高发期。专家提醒，高温天气下人体水分流失加快，加上不良饮食习惯和久坐不动等因素，会显著增加肾结石的发生风险。预防肾结石应牢记三个关键原则：喝够水、管住嘴、迈开腿，从日常生活的细节入手，降低患病几率。 天津市第一中心医院肾内科主任、主任医师常文秀表示，高温天气人体水分从汗液排走，若饮水跟不上，原本溶解在尿液里的钙、草酸、尿酸等物质就会因浓度过高形成结晶，慢慢聚集形成大小不一的结石，就像盐水放久了水分挥发后会析出盐粒一样。 此外，…"
